1	import type { NextRequest } from 'next/server'
2	import { NextResponse } from 'next/server'
3	import { z } from 'zod'
4	import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
5	import { authedRatelimit } from '@/lib/rate-limit'
6	import { logger } from '@/lib/logger'
7	import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'
8	
9	const BodySchema = z.object({
10	  domain: z.string().min(1).max(253),
11	})
12	
13	export async function POST(request: NextRequest) {
14	  const authUser = await getAuthenticatedUser()
15	  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
16	  if (authUser.role !== 'owner') {
17	    return NextResponse.json({ error: 'Forbidden — owner only' }, { status: 403 })
18	  }
19	
20	  const { success } = await authedRatelimit.limit(authUser.user.id)
21	  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
22	
23	  const body = BodySchema.safeParse(await request.json().catch(() => ({})))
24	  if (!body.success) {
25	    return NextResponse.json({ error: body.error.flatten() }, { status: 400 })
26	  }
27	
28	  const supabase = await createClient()
29	
30	  try {
31	    await requireFeatureRpc(supabase, authUser.studioId, 'white_label')
32	  } catch (err) {
33	    if (err instanceof FeatureGateError) {
34	      return NextResponse.json({ error: 'White-label requires Enterprise plan' }, { status: 403 })
35	    }
36	    throw err
37	  }
38	
39	  try {
40	    const { data, error } = await supabase.rpc('verify_custom_domain', {
41	      p_studio_id: authUser.studioId,
42	      p_domain: body.data.domain,
43	    })
44	
45	    if (error) {
46	      logger.error({ err: error, studioId: authUser.studioId }, 'verify_custom_domain rpc failed')
47	      return NextResponse.json({ error: 'Verification failed' }, { status: 500 })
48	    }
49	
50	    return NextResponse.json({ data })
51	  } catch (err) {
52	    logger.error({ err }, 'domain verify unexpected error')
53	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
54	  }
55	}
